/* Cached removal of drawn facial marks plus adjustable procedural expressions. */
(function(){'use strict';const M=Motion,cache=new WeakMap(),clamp=(n,a,b,d)=>Number.isFinite(Number(n))?Math.max(a,Math.min(b,Number(n))):d;
function settings(head,side){const f=head.face||{};return {enabled:f.enabled!==false,x:clamp(f.x,.1,.9,side?(head.flip?.24:.76):.5),eyes:clamp(f.eyes,.2,.85,side?.50:.57),mouth:clamp(f.mouth,.35,.95,side?.70:.81),width:clamp(f.width,.12,.8,side?.16:.55),cover:clamp(f.cover,.5,2,1),ink:/^#[0-9a-f]{6}$/i.test(f.ink)?f.ink:'#574938',patch:/^#[0-9a-f]{6}$/i.test(f.patch)?f.patch:null};}
function cleanImage(head,side){const im=M.img(head.src),f=settings(head,side),key=JSON.stringify(f);let stored=cache.get(head);if(stored?.key===key&&stored.src===head.src)return stored.canvas;const cv=document.createElement('canvas');cv.width=im.naturalWidth;cv.height=im.naturalHeight;const c=cv.getContext('2d');c.drawImage(im,0,0);const pixels=c.getImageData(0,0,cv.width,cv.height),source=new Uint8ClampedArray(pixels.data),w=cv.width,h=cv.height,cx=f.x*w;
// Keep the nose/hair intact; replace only eye/brow and mouth regions. Sample nearby cheek texture once.
const sampleY=Math.round((f.eyes+f.mouth)*.5*h),sampleX=Math.round((side?f.x+(head.flip?.13:-.13):f.x+.18)*w),rgb=f.patch?[1,3,5].map(i=>parseInt(f.patch.slice(i,i+2),16)):null;
for(const [cy,rx,ry] of [[f.eyes*h,f.width*w*.59*f.cover,h*.105*f.cover],[f.mouth*h,f.width*w*.35*f.cover,h*.075*f.cover]]){for(let y=Math.max(0,Math.floor(cy-ry));y<Math.min(h,cy+ry);y++)for(let x=Math.max(0,Math.floor(cx-rx));x<Math.min(w,cx+rx);x++){const d=Math.max(Math.abs((x-cx)/rx),Math.abs((y-cy)/ry));if(d>=1)continue;const a=Math.min(1,(1-d)*7),i=(y*w+x)*4,sx=Math.max(0,Math.min(w-1,sampleX+(x%5)-2)),sy=Math.max(0,Math.min(h-1,sampleY+(y%3)-1)),j=(sy*w+sx)*4;if(source[j+3]<128)continue;for(let k=0;k<3;k++)pixels.data[i+k]=Math.round(source[i+k]*(1-a)+(rgb?rgb[k]:source[j+k])*a);}}
c.putImageData(pixels,0,0);cache.set(head,{key,src:head.src,canvas:c.canvas});return c.canvas;}
function draw(c,head,o,t,x,y,w,h){const im=M.img(head.src),side=o.view==='side',f=settings(head,side),active=o.view!=='back'&&f.enabled&&((o.eyeState&&o.eyeState!=='auto')||o.gaze&&o.gaze!=='direct'||o.emotion!=='neutral'||['talk','cry','laugh','sleep'].includes(o.pose));c.drawImage(active?cleanImage(head,side):im,x,y,w,h);if(!active)return;c.save();c.translate(x,y);c.scale(w/head.width,h/head.height);const sx=f.width*head.width/(side?23:60),cx=f.x*head.width,sign=side&&head.flip?-1:1,ob={...o,gazeMirror:side&&head.flip,faceInk:f.ink};
// Independently align eyes and mouth to the uploaded artwork.
for(const part of ['eyes','mouth']){const cy=(part==='eyes'?f.eyes:f.mouth)*head.height;c.save();c.beginPath();c.rect(0,part==='eyes'?0:(f.eyes+f.mouth)*.5*head.height,head.width,part==='eyes'?(f.eyes+f.mouth)*.5*head.height:head.height);c.clip();c.translate(cx,cy);c.scale(sign*sx,sx);c.translate(side?-20:0,part==='eyes'?-5:-29);M.face(c,ob,t,side);c.restore()}c.restore();}
M.headExpressions={settings,draw};
})();
